<script setup lang="ts">
import{computed,onMounted,onUnmounted,reactive,ref,watch,nextTick}from'vue';
import{newLiquify,LIQUIFY_TOOLS}from'../../../packages/comp-bridge/liquify.mjs';
import{parityMessages}from'./parity-labels';
import type{Language}from'./types';
type Raster={width:number;height:number;data:Uint8ClampedArray};
const props=defineProps<{language:Language;source:Raster;saved?:any;backdrop?:Raster;backdropLoading?:boolean;backdropError?:string}>(),emit=defineEmits(['close','apply','backdrop']);
const t=computed(()=>parityMessages[props.language]),settings=reactive({...newLiquify(props.source.width,props.source.height),...props.saved}),canvas=ref<HTMLCanvasElement>(),viewport=ref<HTMLDivElement>(),busy=ref(true),error=ref(''),canUndo=ref(false),canRedo=ref(false),original=ref(false),working=ref(false),showsFrozen=ref(true),showsMesh=ref(false),showsBackdrop=ref(false),mesh=ref<number[][][]>([]),cursor=ref<number[]>(),fit=ref(true),zoom=ref(1),area=reactive({width:800,height:400}),panning=ref(false);
const factor=computed(()=>fit.value?Math.min(8,Math.max(.01,(area.width-20)/props.source.width),Math.max(.01,(area.height-20)/props.source.height)):zoom.value),surfaceStyle=computed(()=>({width:props.source.width*factor.value+'px',height:props.source.height*factor.value+'px'}));
let worker:Worker,stroke=false,inFlight=false,ending=false,queued:any,frame=0,downPoint:number[]|undefined,stationaryTimer:ReturnType<typeof setInterval>|undefined,space=false,pan:{x:number;y:number;left:number;top:number}|undefined,observer:ResizeObserver,lastImage:Raster|undefined,backdropCanvas:HTMLCanvasElement|undefined,pendingDigit:{digit:number;time:number}|undefined;
const plain=()=>Object.fromEntries(['diameter','hardness','strength','rate','fixedEdges','keepsAlpha','usesPressure','reversesDirection','tool'].map(key=>[key,(settings as any)[key]]));
function send(action:string){if(!worker)return;if(action==='save')busy.value=true;worker.postMessage({action,settings:plain()});}
function draw(image:Raster){lastImage=image;redraw();}
function redraw(){const target=canvas.value,image=original.value?props.source:lastImage;if(!target||!image)return;target.width=image.width;target.height=image.height;const context=target.getContext('2d')!;context.putImageData(new ImageData(new Uint8ClampedArray(image.data),image.width,image.height),0,0);if(showsBackdrop.value&&backdropCanvas){context.save();context.globalCompositeOperation='destination-over';context.globalAlpha=.5;context.drawImage(backdropCanvas,0,0,image.width,image.height);context.restore();}}
function toggleFrozen(){worker?.postMessage({action:'overlay',frozen:showsFrozen.value,mesh:showsMesh.value});}
function toggleBackdrop(){if(showsBackdrop.value&&!props.backdrop)emit('backdrop');redraw();}
function showOriginal(){redraw();}
function scale(multiplier:number){if(busy.value||working.value)return;zoom.value=Math.max(.01,Math.min(20,factor.value*multiplier));fit.value=false;}
function position(event:PointerEvent){const bounds=canvas.value!.getBoundingClientRect();return[(event.clientX-bounds.left)/bounds.width*props.source.width,(event.clientY-bounds.top)/bounds.height*props.source.height,event.pointerType==='pen'?event.pressure:1];}
function flush(){frame=0;if(inFlight||busy.value)return;if(queued){const point=Array.from(queued);queued=undefined;inFlight=true;worker.postMessage({action:'stroke',point,settings:plain()});}else if(ending){ending=false;inFlight=true;send('end');}}
function start(event:PointerEvent){if(busy.value)return;canvas.value!.focus({preventScroll:true});if(space||event.button===1){if(!viewport.value)return;pan={x:event.clientX,y:event.clientY,left:viewport.value.scrollLeft,top:viewport.value.scrollTop};panning.value=true;canvas.value!.setPointerCapture(event.pointerId);event.preventDefault();return;}if(original.value||event.button!==0)return;stroke=true;working.value=true;canvas.value!.setPointerCapture(event.pointerId);downPoint=position(event);cursor.value=downPoint;queued=downPoint;flush();stationaryTimer=setInterval(()=>{if(stroke&&settings.tool!=='Forward Warp'&&!busy.value){queued=downPoint;flush();}},75);}
function move(event:PointerEvent){if(pan&&viewport.value){viewport.value.scrollLeft=pan.left+pan.x-event.clientX;viewport.value.scrollTop=pan.top+pan.y-event.clientY;return;}cursor.value=position(event);if(!stroke)return;downPoint=cursor.value;queued=downPoint;if(!frame)frame=requestAnimationFrame(flush);}
function end(){if(pan){pan=undefined;panning.value=false;return;}if(!stroke)return;stroke=false;ending=true;clearInterval(stationaryTimer);flush();}
function key(event:KeyboardEvent){if(event.isComposing||event.target instanceof HTMLElement&&event.target.closest('input,textarea,select,button,[contenteditable]')||busy.value||working.value)return;if(event.code==='Space'){event.preventDefault();event.stopPropagation();space=true;return;}if(event.ctrlKey||event.metaKey||event.altKey)return;const bracket=event.code==='BracketLeft'?'[':event.code==='BracketRight'?']':event.key;if(['[',']','{','}'].includes(bracket)){event.preventDefault();event.stopPropagation();const increase=bracket===']'||bracket==='}';if(event.shiftKey){const quarter=settings.hardness*4,step=increase?Math.floor(quarter+.001)+1:Math.ceil(quarter-.001)-1;settings.hardness=Math.max(0,Math.min(4,step))/4;}else settings.diameter=Math.max(2,Math.min(3000,increase?Math.max(settings.diameter+1,Math.round(settings.diameter*1.2)):Math.min(settings.diameter-1,Math.round(settings.diameter/1.2))));return;}if(/^\d$/.test(event.key)&&!event.shiftKey){event.preventDefault();event.stopPropagation();const digit=Number(event.key),now=performance.now();if(pendingDigit&&now-pendingDigit.time<600){settings.strength=Math.max(1,pendingDigit.digit*10+digit)/100;pendingDigit=undefined;}else{settings.strength=(digit===0?100:digit*10)/100;pendingDigit={digit,time:now};}}}
const undo=()=>{if(!busy.value&&!working.value&&canUndo.value&&!document.activeElement?.closest('input,textarea,select,[contenteditable]'))send('undo');},redo=()=>{if(!busy.value&&!working.value&&canRedo.value&&!document.activeElement?.closest('input,textarea,select,[contenteditable]'))send('redo');};
const stopUndo=window.editor.onCommand('undo',undo),stopRedo=window.editor.onCommand('redo',redo);
watch(()=>props.backdrop,async value=>{if(backdropCanvas)backdropCanvas.width=backdropCanvas.height=1;backdropCanvas=undefined;if(value){const surface=document.createElement('canvas');surface.width=value.width;surface.height=value.height;surface.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(value.data),value.width,value.height),0,0);backdropCanvas=surface;}await nextTick();redraw();});
onMounted(()=>{observer=new ResizeObserver(entries=>{const rect=entries[0].contentRect;area.width=rect.width;area.height=rect.height;});observer.observe(viewport.value!);worker=new Worker(new URL('./liquify-worker.ts',import.meta.url),{type:'module'});worker.onmessage=event=>{inFlight=false;if(event.data.error){error.value=t.value.failed;busy.value=false;working.value=false;return;}if(event.data.saved){emit('apply',event.data.saved);return;}draw(event.data.image);mesh.value=event.data.mesh??[];canUndo.value=event.data.canUndo;canRedo.value=event.data.canRedo;busy.value=false;if(queued||ending)flush();else if(!stroke)working.value=false;};worker.onerror=()=>{error.value=t.value.failed;busy.value=false;working.value=false;};worker.postMessage({action:'init',source:props.source,saved:props.saved?JSON.parse(JSON.stringify(props.saved)):undefined});});
onUnmounted(()=>{observer?.disconnect();cancelAnimationFrame(frame);clearInterval(stationaryTimer);worker?.terminate();stopUndo();stopRedo();if(backdropCanvas)backdropCanvas.width=backdropCanvas.height=1;lastImage=undefined;});
</script>
<template><div class="modal-shade"><section role="dialog" aria-modal="true" :aria-label="t.liquify" class="dialog liquify-dialog" @keydown="key" @keyup.space="space=false" @keydown.esc.stop.prevent="emit('close')"><h2>{{t.liquify}}</h2><p v-if="error||backdropError" role="alert">{{error||backdropError}}</p><p>{{t.liquifyTip}} {{t.liquifyKeys}}</p><fieldset :disabled="busy||working"><div class="style-fields"><label>{{t.tool}}<select v-model="settings.tool" data-testid="liquify-tool"><option v-for="(tool,index) in LIQUIFY_TOOLS" :key="tool" :value="tool">{{t.liquifyTools[index]}}</option></select></label><label>{{t.diameter}}<input v-model.number="settings.diameter" data-testid="liquify-diameter" type="number" min="2" max="3000"></label><label>{{t.hardness}}<input v-model.number="settings.hardness" data-testid="liquify-hardness" type="number" min="0" max="1" step=".01"></label><label>{{t.strength}}<input v-model.number="settings.strength" data-testid="liquify-strength" type="number" min=".01" max="1" step=".01"></label><label>{{t.rate}}<input v-model.number="settings.rate" type="number" min=".1" max="3" step=".1"></label></div><div class="button-row"><label><input v-model="settings.fixedEdges" type="checkbox">{{t.fixedEdges}}</label><label><input v-model="settings.keepsAlpha" type="checkbox">{{t.keepAlpha}}</label><label><input v-model="settings.usesPressure" type="checkbox">{{t.pressure}}</label><label><input v-model="settings.reversesDirection" type="checkbox">{{t.reverse}}</label><label><input v-model="showsFrozen" type="checkbox" @change="toggleFrozen">{{t.showFrozen}}</label><label><input v-model="showsMesh" data-testid="liquify-mesh" type="checkbox" @change="toggleFrozen">{{t.showMesh}}</label><label><input v-model="showsBackdrop" data-testid="liquify-backdrop" type="checkbox" :disabled="backdropLoading" @change="toggleBackdrop">{{t.showBackdrop}}</label><label><input v-model="original" type="checkbox" @change="showOriginal">{{t.before}}</label></div></fieldset><div class="button-row"><button type="button" :disabled="busy||working" @click="fit=true">{{t.fit}}</button><button type="button" :disabled="busy||working" @click="scale(.8)">−</button><button type="button" :disabled="busy||working" data-testid="liquify-actual" @click="zoom=1;fit=false">{{Math.round(factor*100)}}%</button><button type="button" :disabled="busy||working" data-testid="liquify-zoom-in" @click="scale(1.25)">+</button><span v-if="backdropLoading" role="status">{{t.loading}}</span></div><div ref="viewport" class="liquify-viewport" data-testid="liquify-viewport" :class="{panning}" @wheel.ctrl.prevent="scale($event.deltaY<0?1.1:1/1.1)"><div class="liquify-surface" :style="surfaceStyle"><canvas ref="canvas" tabindex="0" data-testid="liquify-canvas" :aria-label="t.liquify" @pointerdown="start" @pointermove="move" @pointerup="end" @pointercancel="end" @pointerleave="!working&&(cursor=undefined)" @blur="space=false"></canvas><svg :viewBox="`0 0 ${source.width} ${source.height}`" preserveAspectRatio="none" aria-hidden="true"><g v-if="showsMesh" data-testid="liquify-mesh-lines"><polyline v-for="(line,index) in mesh" :key="index" :points="line.map(point=>point.join(',')).join(' ')" fill="none" stroke="#4ee8ef" stroke-opacity=".6" stroke-width="1" vector-effect="non-scaling-stroke"/></g><g v-if="cursor&&!panning"><circle :cx="cursor[0]" :cy="cursor[1]" :r="settings.diameter/2" fill="none" stroke="#111" stroke-width="3" vector-effect="non-scaling-stroke"/><circle :cx="cursor[0]" :cy="cursor[1]" :r="settings.diameter/2" fill="none" stroke="#fff" stroke-width="1" vector-effect="non-scaling-stroke"/></g></svg></div></div><div class="button-row"><button :disabled="busy||working||!canUndo" @click="send('undo')">{{t.undo}}</button><button :disabled="busy||working||!canRedo" @click="send('redo')">{{t.redo}}</button><button :disabled="busy||working" @click="send('reset')">{{t.reconstructAll}}</button></div><div class="button-row dialog-actions"><button @click="emit('close')">{{t.cancel}}</button><button class="primary" data-testid="apply-liquify" :disabled="busy||working||!!error" @click="send('save')">{{t.apply}}</button></div></section></div></template>
<style scoped>.liquify-dialog{width:min(1000px,95vw);max-height:94vh;overflow:auto}.liquify-dialog canvas{display:block;max-width:100%;max-height:46vh;object-fit:contain;margin:auto;touch-action:none;background:repeating-conic-gradient(#666 0 25%,#888 0 50%) 0/16px 16px}.liquify-dialog fieldset{border:0;padding:0}.liquify-dialog .button-row>label{display:flex;align-items:center;gap:4px}.liquify-viewport{width:100%;height:46vh;overflow:auto;background:repeating-conic-gradient(#444 0 25%,#666 0 50%) 0/16px 16px}.liquify-surface{position:relative;margin:auto}.liquify-surface canvas{display:block;width:100%;height:100%;max-width:none;max-height:none;object-fit:fill;margin:0;background:transparent;touch-action:none;cursor:crosshair}.liquify-surface svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.liquify-viewport.panning canvas{cursor:grabbing}</style>
